// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint256).max / 2);
        // owner of c is this test contract (deployer); owner calls sudicideAnyone
        vm.deal(address(this), amount);
        vm.deal(address(c), amount);
        uint256 ownerBefore = address(this).balance;
        c.sudicideAnyone();
        // RULE: the self-destruct proceeds must go to the beneficiary == caller (owner),
        // so the owner's balance increases by the destroyed contract's balance.
        assertTrue(address(c).balance == 0 && address(this).balance == ownerBefore + amount);
    }
}
